package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class SolidGeometrySvgRenderer { public String render(SolidGeometryDiagramSpecV1 s){int p=s.viewport().padding(),w=s.viewport().width(),h=s.viewport().height(),dx=40,dy=23;var b=new StringBuilder("<polygon points=\"").append(p).append(",").append(h-p).append(" ").append(w-p).append(",").append(h-p).append(" ").append(w-p-dx).append(",").append(p+dy).append(" ").append(p+dx).append(",").append(p).append("\" fill=\"none\" stroke=\"#000000\"/>").append("<line x1=\"").append(p).append("\" y1=\"").append(h-p).append("\" x2=\"").append(p+dx).append("\" y2=\"").append(p).append("\" stroke=\"#000000\" stroke-dasharray=\"4 3\"/>");for(var label:s.labels())b.append("<text x=\"").append(p+8).append("\" y=\"").append(p+18).append("\">").append(escape(label.labelTemplate())).append("</text>");return b.toString();}private String escape(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
